contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters to drive deposit and withdraw
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        // make a deposit on c from this contract
        c.deposit{value: depositAmount}();

        // record balances after deposit and before withdraw
        uint afterDepositC = address(c).balance;
        uint afterDepositSelf = address(this).balance;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record balances after withdraw attempt
        uint finalC = address(c).balance;
        uint finalSelf = address(this).balance;

        // General rule:
        // If withdrawAll reverted then final balances equal afterDeposit balances.
        // If withdrawAll did not revert then the decrease in c's balance equals the increase in this contract's balance.
        assert(
            reverted
            ? (finalC == afterDepositC && finalSelf == afterDepositSelf)
            : (afterDepositC >= finalC && finalSelf >= afterDepositSelf && (afterDepositC - finalC) == (finalSelf - afterDepositSelf))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will use an input amount to deposit into c, then call withdrawAll(),
    // and finally observe that address(c).balance did not increase and that a subsequent
    // deposit of 0 followed by withdrawAll() will not try to withdraw a positive amount from c
    // (i.e., after a successful withdrawAll the contract no longer holds credit for this caller).
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for test deposit");

        // Record c's balance before any interaction
        uint beforeC = address(c).balance;

        // Make a deposit from this test contract to c of depositAmount
        c.deposit{value: depositAmount}();

        // Now call withdrawAll and catch whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record c's balance after withdrawAll
        uint afterC = address(c).balance;

        // To check that withdraw cleared the caller's credit when it did not revert,
        // we perform a zero-value deposit (no state change except credit increase of 0)
        // and then call withdrawAll() again; if earlier withdraw cleared credit, this second
        // withdrawAll should not change c's balance (it should withdraw 0) and should not revert.
        // We perform it and observe whether it reverts and the resulting balance.
        bool revertedSecond;
        uint beforeSecond = afterC;
        // zero-value deposit is allowed and is a visible call
        c.deposit{value: 0}();
        try c.withdrawAll() {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }
        uint afterSecond = address(c).balance;

        // General rule asserted:
        // - withdrawAll never increases c's balance: afterC <= beforeC OR withdrawAll reverted.
        // - If the first withdrawAll succeeded (not reverted) then the second withdrawAll (after a 0 deposit)
        //   must succeed and must not decrease c's balance (i.e., it withdraws 0), so afterSecond == beforeSecond.
        assert(
            // Either the first withdrawAll reverted (no guarantees), or it did not increase c's balance
            (reverted || afterC <= beforeC)
            &&
            // If first succeeded, then second must succeed and not change balance (credit cleared)
            (reverted || (!reverted && !revertedSecond && afterSecond == beforeSecond))
        );
    }

    receive() external payable { }
}

