    // We will: optionally deposit 'amt' into c, then call withdrawAll() once (catching revert).
    // After a successful withdrawAll, a second withdrawAll must not send any more funds to this contract
    // because credit[msg.sender] should be zero. We observe this by checking that address(this).balance
    // does not increase on the second call (we detect success/failure by try/catch and balances).

    function run(uint amt) public payable {
        require(address(this).balance >= amt);

        // Record balances before any action
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // If amt > 0 deposit into c
        if (amt > 0) {
            c.deposit{value: amt}();
        }

        // Attempt first withdrawAll
        bool firstReverted;
        uint afterFirstThis;
        uint afterFirstC;
        try c.withdrawAll() {
            firstReverted = false;
            afterFirstThis = address(this).balance;
            afterFirstC = address(c).balance;
        } catch {
            firstReverted = true;
            afterFirstThis = address(this).balance;
            afterFirstC = address(c).balance;
        }

        // Attempt second withdrawAll to check idempotence: if first succeeded, second should not change balances
        bool secondReverted;
        uint afterSecondThis;
        uint afterSecondC;
        try c.withdrawAll() {
            secondReverted = false;
            afterSecondThis = address(this).balance;
            afterSecondC = address(c).balance;
        } catch {
            secondReverted = true;
            afterSecondThis = address(this).balance;
            afterSecondC = address(c).balance;
        }

        // General rule asserted:
        // If the first withdrawAll succeeded (did not revert) then the second withdrawAll must not transfer any more Ether to this contract
        // and C's balance must not decrease further. That is, afterFirstThis == afterSecondThis and afterFirstC == afterSecondC.
        // If the first withdrawAll reverted, we do not constrain the second call.
        assert(firstReverted || (afterFirstThis == afterSecondThis && afterFirstC == afterSecondC));
    }

