        // - If the first withdraw was not attempted (doFirstWithdraw==false), treat as no first withdraw: then the probe may behave freely, so no constraint beyond reaching the assert.
        assert(
            (doFirstWithdraw == true && firstReverted == false) ? (probeAfterC == probeBeforeC && probeAfterThis == probeBeforeThis) :
            (doFirstWithdraw == true && firstReverted == true) ? (afterFirstC == afterDepositC) :
            true
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit first, then attempt withdrawAll().
    // amount may be zero. We must fund this contract to send Ether when calling deposit.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Record C's observable balance before any interaction
        uint beforeC = address(c).balance;

        // Deposit amount into C (may be zero)
        c.deposit{value: amount}();

        // After deposit, recorded credit for this contract as seen by C is unknown (no getter),
        // but we can observe balances. Record C's balance after deposit.
        uint afterDepositC = address(c).balance;

        // Try withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe C's balance after the withdraw attempt
        uint afterWithdrawC = address(c).balance;

        // General rule (single assert):
        // 1) withdrawAll never increases C's balance: afterWithdrawC <= afterDepositC
        // 2) If withdrawAll did not revert then C's balance decreased by at most the amount we deposited
        //    and decreased by exactly the previous credited amount (which cannot exceed amount). We cannot read credit directly,
        //    but we can assert that if it didn't revert then the decrease is <= afterDepositC - beforeC (i.e., <= amount)
        //    and also the balance change equals (afterDepositC - afterWithdrawC) >= 0.
        // Combining a useful invariant that distinguishes faulty code: ensure no increase and any successful call does not decrease by more than the deposited amount.

        assert(afterWithdrawC <= afterDepositC && (
            reverted || (afterDepositC - afterWithdrawC <= afterDepositC - beforeC)
        ));
    }

    receive() external payable {}
}
